-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.save_anki_notes(items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  x jsonb;
  changed jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(items) is distinct from 'array' then
    raise exception 'save_anki_notes: items has to be an array';
  end if;
  if jsonb_array_length(items) > 1000 then
    raise exception 'save_anki_notes: at most 1000 notes per call';
  end if;
  for x in select v from jsonb_array_elements(items) as v loop
    if public.save_anki_note(x) then
      changed := changed || to_jsonb(x ->> 'guid');
    end if;
  end loop;
  return changed;
end;
$function$;

grant execute on function public.save_anki_notes(items jsonb) to service_role;
